SELECT "author"."address" AS "author.address", "author"."birthday" AS "author.birthday", "author"."created_at" AS "author.created_at", "author"."email" AS "author.email", "author"."email_verified" AS "author.email_verified", "author"."first_name" AS "author.first_name", "author"."gender" AS "author.gender", "author"."id" AS "author.id", "author"."last_name" AS "author.last_name", "author"."updated_at" AS "author.updated_at", "post"."content" AS "post.content", "post"."created_at" AS "post.created_at", "post"."id" AS "post.id", "post"."title" AS "post.title", "post"."updated_at" AS "post.updated_at", "post"."user_id" AS "post.user_id" FROM "posts" AS "post" INNER JOIN "users" AS "author" ON ("author"."id" = "post"."user_id") WHERE ("post"."id" = '00000000-0000-0000-0001-000000000001') LIMIT 1;
